-- Synthetic metadata only, rolled back. No account or object persists.
begin;
set local statement_timeout='60s';
select set_config('t026.user',gen_random_uuid()::text,true),set_config('t026.other',gen_random_uuid()::text,true),set_config('t026.session',gen_random_uuid()::text,true),set_config('t026.book',gen_random_uuid()::text,true),set_config('t026.page',gen_random_uuid()::text,true),set_config('t026.account',gen_random_uuid()::text,true);
create function pg_temp.search_assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'T026 behavior: %',message;end if;end $$;
create function pg_temp.search_error(command text,expected text) returns void language plpgsql as $$declare actual text;detail text;context text;begin begin execute command;exception when others then get stacked diagnostics actual=returned_sqlstate,detail=message_text,context=pg_exception_context;if actual<>expected then raise exception 'Expected %, got %: % / %',expected,actual,detail,left(context,350);end if;return;end;raise exception 'Expected %, succeeded',expected;end $$;
create function pg_temp.search_file(name text,kind text default 'drive',owner uuid default current_setting('t026.user')::uuid) returns void language plpgsql as $$declare id uuid:=gen_random_uuid();p jsonb;begin p:=jsonb_build_object('id',id,'user_id',owner,'kind',kind,'folder_id',null,'name',name,'mime',case when kind='drive' then 'text/plain' else 'image/png' end,'bytes',10,'sha256',repeat('a',64),'width',case when kind='drive' then null else 20 end,'height',case when kind='drive' then null else 20 end,'starred',false,'deleted_at',null,'deletion_batch_id',null,'created_at',now(),'updated_at',now(),'modified_at',now());insert into public.drive_files(id,user_id,payload,kind,name,mime,bytes,sha256,storage_path,created_at,updated_at) values(id,owner,p,kind,name,p->>'mime',10,repeat('a',64),owner::text||'/'||id::text,now(),now());end $$;
do $$declare schema_name text;begin select nspname into schema_name from pg_namespace where oid=pg_my_temp_schema();execute format('grant usage on schema %I to service_role,authenticated',schema_name);execute format('grant execute on all functions in schema %I to service_role,authenticated',schema_name);end $$;
