insert into auth.sessions(id,user_id,created_at,updated_at) values(current_setting('t026.session')::uuid,current_setting('t026.user')::uuid,now(),now());
select pg_temp.search_file('Ação PESSOAL');select pg_temp.search_file('Outra ação pessoal');select pg_temp.search_file('100%_literal.txt');select pg_temp.search_file('100xxliteral.txt');select pg_temp.search_file('Ação privada de anexo.png','capture_image');select pg_temp.search_file('Ação outro dono','drive',current_setting('t026.other')::uuid);
insert into public.projects(payload) values(jsonb_build_object('id',gen_random_uuid(),'user_id',current_setting('t026.user'),'name','Ação projeto','description','Contexto privado','color_key','work','position',0,'deleted_at',null,'created_at',now(),'updated_at',now()));
insert into public.habits(payload) values(jsonb_build_object('id',gen_random_uuid(),'user_id',current_setting('t026.user'),'name','Ação hábito','schedule_kind','daily','weekdays','[]'::jsonb,'weekly_target',null,'started_on','2026-01-01','color_key','personal','icon_key',null,'position',0,'archived_at',null,'created_at',now(),'updated_at',now()));
