insert into public.tasks(payload) values(jsonb_build_object('id',gen_random_uuid(),'user_id',current_setting('t026.user'),'client_id','search-task','title','Ação tarefa','description',null,'category_id',null,'project_id',null,'status','todo','priority','medium','due_at',null,'scheduled_start_at',null,'scheduled_end_at',null,'all_day',false,'estimated_minutes',null,'board_position',null,'source','manual','origin_capture_id',null,'completed_at',null,'archived_at',null,'deleted_at',null,'created_at',now(),'updated_at',now()));
insert into public.knowledge_notebooks(id,user_id,payload) values(current_setting('t026.book')::uuid,current_setting('t026.user')::uuid,jsonb_build_object('id',current_setting('t026.book'),'user_id',current_setting('t026.user'),'name','Busca','project_id',null,'position',0,'deleted_at',null,'deletion_batch_id',null,'created_at',now(),'updated_at',now()));
insert into public.knowledge_pages(id,user_id,payload) values(current_setting('t026.page')::uuid,current_setting('t026.user')::uuid,jsonb_build_object('id',current_setting('t026.page'),'user_id',current_setting('t026.user'),'notebook_id',current_setting('t026.book'),'parent_id',null,'origin_capture_id',null,'title','Ação página','normalized_title','acao pagina','document','{"type":"doc","content":[{"type":"paragraph"}]}'::jsonb,'content_text','','version',1,'position',0,'archived_at',null,'deleted_at',null,'deletion_batch_id',null,'created_at',now(),'updated_at',now()));
insert into public.fin_accounts(payload) values(jsonb_build_object('id',current_setting('t026.account'),'user_id',current_setting('t026.user'),'name','Conta','kind','checking','institution',null,'currency','BRL','opening_balance_cents',0,'color_key','fin-1','archived_at',null,'credit_limit_cents',null,'statement_closing_day',null,'payment_due_day',null,'created_at',now(),'updated_at',now()));
insert into public.fin_transactions(payload) values(jsonb_build_object('id',gen_random_uuid(),'user_id',current_setting('t026.user'),'account_id',current_setting('t026.account'),'category_id',null,'kind','expense','amount_cents',123456789,'paid_cents',123456789,'description','Ação financeira','payee',null,'occurred_on','2026-10-09','transfer_group_id',null,'notes','Texto privado que não sai','installment_group_id',null,'installment_no',null,'installment_total',null,'statement_month',null,'serie_tipo',null,'status','confirmed','source','manual','due_date',null,'deleted_at',null,'created_at',now(),'updated_at',now()));
set local role service_role;
do $$declare u uuid:=current_setting('t026.user')::uuid;s uuid:=current_setting('t026.session')::uuid;items jsonb;item jsonb;begin
 items:=public.global_search(u,s,'AÇÃO');perform pg_temp.search_assert(jsonb_array_length(items)=8,'seven permitted types plus second Drive file');perform pg_temp.search_assert(not exists(select 1 from jsonb_array_elements(items) x where x->>'user_id'<>u::text or x->>'title' like '%outro dono%' or x->>'title' like '%anexo%'),'owner and Drive-only scope');perform pg_temp.search_assert(items::text not like '%123456789%' and items::text not like '%Texto privado%','no financial values or bodies in descriptors');
 for item in select value from jsonb_array_elements(items) loop perform pg_temp.search_assert(item-array['id','user_id','type','title','rank']='{}'::jsonb,'closed descriptor DTO');end loop;
 items:=public.global_search(u,s,'acao pessoal');perform pg_temp.search_assert(items->0->>'title'='Ação PESSOAL' and items->0->>'rank'='0','accent/case exact title first');
 items:=public.global_search(u,s,'100%_');perform pg_temp.search_assert(jsonb_array_length(items)=1 and items->0->>'title'='100%_literal.txt','LIKE wildcards treated literally');
 perform pg_temp.search_assert(public.global_search(u,s,'   ')='[]'::jsonb,'empty search');perform pg_temp.search_error(format('select public.global_search(%L,%L,%L)',u,s,repeat('x',121)),'22023');perform pg_temp.search_error(format('select public.global_search(%L,%L,''acao'')',current_setting('t026.other'),s),'42501');
end $$;
reset role;
