select pg_temp.search_assert(exists(select 1 from jsonb_array_elements(public.global_search(current_setting('t026.user')::uuid,current_setting('t026.session')::uuid,'acao')) x where x->>'type'='file'),'hidden preference remains searchable');
insert into public.user_entitlements(user_id,feature_key,allowed) values(current_setting('t026.user')::uuid,'drive',false);
select pg_temp.search_assert(not exists(select 1 from jsonb_array_elements(public.global_search(current_setting('t026.user')::uuid,current_setting('t026.session')::uuid,'acao')) x where x->>'type'='file'),'veto skips source');
update public.user_moderation set must_change_password=true where user_id=current_setting('t026.user')::uuid;
select pg_temp.search_error(format('select public.global_search(%L,%L,''acao'')',current_setting('t026.user'),current_setting('t026.session')),'42501');
update public.user_moderation set must_change_password=false,status='blocked' where user_id=current_setting('t026.user')::uuid;
select pg_temp.search_error(format('select public.global_search(%L,%L,''acao'')',current_setting('t026.user'),current_setting('t026.session')),'42501');
set local role authenticated;
select pg_temp.search_error(format('select public.global_search(%L,%L,''acao'')',current_setting('t026.user'),current_setting('t026.session')),'42501');
rollback;
